import {parseBib,connections,validateWorkspace,normalizeDoi} from './core.js';
const $=s=>document.querySelector(s),NS='http://www.w3.org/2000/svg',KEY='atlas-library-v1';
let state={version:1,papers:[],manual:[]},selected=null,edges=[],positions=new Map(),view={x:0,y:0,k:1},busy=false;
const colors={topic:'#6b947c',citation:'#b28a51',manual:'#9982b6'},types={topic:'Términos compartidos',citation:'Cita en Crossref',manual:'Conexión personal'};
function el(tag,attrs={},text){const n=document.createElement(tag);for(const [k,v]of Object.entries(attrs))n.setAttribute(k,v);if(text!==undefined)n.textContent=text;return n}
function svg(tag,attrs={},text){const n=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))n.setAttribute(k,v);if(text!==undefined)n.textContent=text;return n}
function notice(s){$('#notice').textContent=s}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('#saveState').textContent='✓ Guardado en este navegador'}catch{notice('No se ha podido guardar en este navegador. Exporta la biblioteca para conservarla.')}}
function visible(){let q=$('#search').value.toLowerCase(),st=$('#statusFilter').value;return state.papers.filter(p=>(!st||p.status===st)&&[p.title,p.authors,p.keywords,p.abstract].join(' ').toLowerCase().includes(q))}
function activeEdges(){let ids=new Set(visible().map(p=>p.id));return edges.filter(e=>ids.has(e.source)&&ids.has(e.target)&&$('#'+({topic:'topics',citation:'citations',manual:'manual'}[e.type])).checked)}
function refresh(recompute=true){if(recompute)edges=connections(state.papers,state.manual);const papers=visible();$('#paperCount').textContent=state.papers.length;$('#readCount').textContent=state.papers.filter(p=>p.status==='Leído').length;$('#linkCount').textContent=activeEdges().length;$('#listCount').textContent=papers.length;$('#paperList').replaceChildren();for(const p of papers){const b=el('button',{class:'paper'+(selected===p.id?' active':'')});b.append(el('small',{},(p.authors.split(' and ')[0]||p.id)+' · '+(p.year||'s. f.')),el('strong',{},p.title),el('span',{class:'state'},p.status));b.onclick=()=>select(p.id);$('#paperList').append(b)}if(!papers.length)$('#paperList').append(el('p',{},state.papers.length?'No hay coincidencias.':'Importa un .bib para empezar.'));let looked=state.papers.filter(p=>p.lookup==='ok').length;$('#coverage').textContent=looked?`Crossref consultado: ${looked}/${state.papers.length}. La ausencia de enlace no descarta una relación.`:'Conexiones iniciales por términos; no demuestran una relación científica.';draw();details()}
function select(id){selected=id;refresh(false)}
function draw(){const papers=visible(),links=activeEdges();$('#emptyGraph').hidden=!!papers.length;$('#nodes').replaceChildren();$('#edges').replaceChildren();papers.forEach((p,i)=>{if(!positions.has(p.id)){const a=i*2.39996,r=80+220*Math.sqrt(i/Math.max(1,papers.length));positions.set(p.id,{x:450+Math.cos(a)*r,y:335+Math.sin(a)*r})}});
 for(const e of links){const a=positions.get(e.source),b=positions.get(e.target);let line=svg('line',{x1:a.x,y1:a.y,x2:b.x,y2:b.y,stroke:colors[e.type],'stroke-width':e.type==='topic'?1.5+e.score*3:2,class:'edge',tabindex:0,role:'button','aria-label':e.reason});if(e.type==='citation')line.setAttribute('marker-end','url(#arrow)');if(e.type==='manual')line.setAttribute('stroke-dasharray','5 4');line.append(svg('title',{},e.reason));const explain=()=>{notice(types[e.type]+' · '+e.reason);select(e.source)};line.onclick=explain;line.onkeydown=ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();explain()}};$('#edges').append(line)}
 for(const p of papers){const pos=positions.get(p.id),n=links.filter(e=>e.source===p.id||e.target===p.id).length,r=18+Math.min(n,12)*1.1;let g=svg('g',{class:'node',transform:`translate(${pos.x} ${pos.y})`,tabindex:0,role:'button','aria-label':p.title});g.append(svg('circle',{r:r+7,fill:selected===p.id?'#d4e5d7':'#f3f5ee',stroke:'none'}),svg('circle',{r,fill:selected===p.id?'#294e3d':p.status==='Leído'?'#81a587':'#d2dfca',stroke:'#fdfdf9','stroke-width':3}),svg('text',{'text-anchor':'middle',y:4,'font-size':10,fill:selected===p.id?'white':'#35523e'},p.year||'·'),svg('text',{'text-anchor':'middle',y:r+24,'font-size':11,fill:'#3f5547'},(p.authors.split(',')[0].split(' and ')[0]||p.id).slice(0,19)));g.append(svg('title',{},p.title));g.onclick=()=>select(p.id);g.onkeydown=ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();select(p.id)}};g.onpointerdown=ev=>{ev.stopPropagation();g.setPointerCapture(ev.pointerId);let moved=false,start={x:ev.clientX,y:ev.clientY};g.onpointermove=e=>{if(Math.hypot(e.clientX-start.x,e.clientY-start.y)>3)moved=true;if(!moved)return;let pt=point(e);positions.set(p.id,{x:(pt.x-view.x)/view.k,y:(pt.y-view.y)/view.k});g.setAttribute('transform',`translate(${positions.get(p.id).x} ${positions.get(p.id).y})`);for(const line of $('#edges').children){/* Connections are refreshed after dragging. */}};g.onpointerup=()=>{g.onpointermove=null;selected=p.id;refresh(false)}};$('#nodes').append(g)}applyView()}
function safeUrl(s){try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:null}catch{return null}}
function details(){const box=$('#detailContent');box.replaceChildren();const p=state.papers.find(p=>p.id===selected);if(!p){let d=el('div',{class:'empty-detail'});d.append(el('span',{},'↖'),el('h2',{},'Empieza por una pregunta.'),el('p',{},'Selecciona un artículo para explorar sus conexiones, abrir el original y guardar tus notas.'));box.append(d);return}box.append(el('div',{class:'eyebrow'},'FICHA DE LECTURA · '+p.id),el('h3',{},p.title),el('p',{class:'meta'},[p.authors.replaceAll(' and ','; '),p.journal,p.year].filter(Boolean).join(' · ')));const url=safeUrl(p.doi?'https://doi.org/'+p.doi:p.url);if(url)box.append(el('a',{href:url,target:'_blank',rel:'noopener noreferrer'},'Abrir artículo ↗'));box.append(el('label',{for:'reading'},'Mi lectura'));const status=el('select',{id:'reading'});for(const s of ['Pendiente','Leyendo','Leído'])status.append(el('option',{value:s},s));status.value=p.status;status.onchange=()=>{p.status=status.value;save();refresh(false)};box.append(status);box.append(el('label',{for:'notes'},'Ideas, dudas y conexiones'));const notes=el('textarea',{id:'notes',placeholder:'¿Qué aporta a mi tesis? ¿Qué método o resultado quiero recordar?'});notes.value=p.notes||'';notes.oninput=()=>{p.notes=notes.value;save()};box.append(notes);
 if(p.abstract){const d=el('details');d.append(el('summary',{},'Leer resumen disponible'),el('p',{},p.abstract));box.append(d)}box.append(el('p',{class:'small'},p.lookup==='ok'?'Metadatos consultados en Crossref.':p.lookup==='error'?'No se pudieron recuperar metadatos de Crossref.':p.doi?'Sin consulta de Crossref todavía.':'Sin DOI: añade relaciones personales.'));
 box.append(el('h4',{},'CONEXIONES VISIBLES'));let links=activeEdges().filter(e=>e.source===p.id||e.target===p.id);for(const e of links){let other=state.papers.find(x=>x.id===(e.source===p.id?e.target:e.source));const b=el('button',{class:'connection'});b.append(el('span',{},other.title),el('small',{},types[e.type]+(e.type==='citation'?(e.source===p.id?' · cita este artículo':' · cita el seleccionado'):'')),el('small',{},e.reason));b.onclick=()=>select(other.id);box.append(b);if(e.type==='manual'){const remove=el('button',{class:'small'},'Eliminar conexión personal');remove.onclick=()=>{state.manual=state.manual.filter(x=>x!==e);save();refresh()};box.append(remove)}}if(!links.length)box.append(el('p',{class:'small'},'Sin conexiones con las capas y filtros actuales.'));
 if(state.papers.length>1){box.append(el('h4',{},'AÑADIR MI CONEXIÓN'));const pick=el('select',{'aria-label':'Artículo para conectar'});for(const other of state.papers.filter(x=>x.id!==p.id))pick.append(el('option',{value:other.id},other.title));const reason=el('input',{placeholder:'¿Qué relación tienen?','aria-label':'Motivo de la conexión'}),add=el('button',{id:'addLink'},'Guardar conexión');add.onclick=()=>{if(!reason.value.trim()){reason.focus();return}state.manual.push({source:p.id,target:pick.value,type:'manual',reason:reason.value.trim(),score:1});save();refresh()};box.append(pick,reason,add)}}
function point(ev){let pt=$('#graph').createSVGPoint();pt.x=ev.clientX;pt.y=ev.clientY;return pt.matrixTransform($('#graph').getScreenCTM().inverse())}function applyView(){$('#viewport').setAttribute('transform',`translate(${view.x} ${view.y}) scale(${view.k})`)}
$('#graph').addEventListener('wheel',ev=>{ev.preventDefault();const pt=point(ev),k=Math.max(.3,Math.min(4,view.k*Math.exp(-ev.deltaY*.001)));view.x=pt.x-(pt.x-view.x)*k/view.k;view.y=pt.y-(pt.y-view.y)*k/view.k;view.k=k;applyView()},{passive:false});$('#graph').onpointerdown=ev=>{if(ev.target.closest('.node,.edge'))return;const start=point(ev),origin={...view};$('#graph').setPointerCapture(ev.pointerId);$('#graph').onpointermove=e=>{const p=point(e);view.x=origin.x+p.x-start.x;view.y=origin.y+p.y-start.y;applyView()};$('#graph').onpointerup=()=>{$('#graph').onpointermove=null}};$('#fit').onclick=()=>{view={x:0,y:0,k:1};applyView()};for(const id of ['search','statusFilter','topics','citations','manual'])$('#'+id).addEventListener(id==='search'?'input':'change',()=>refresh(false));
async function loadDemo(){if(state.papers.length&&!confirm('¿Reemplazar la biblioteca actual por el ejemplo? Exporta antes si quieres conservarla.'))return;try{const res=await fetch('example.bib');if(!res.ok)throw Error('No se pudo abrir el ejemplo.');replace({version:1,papers:parseBib(await res.text()),manual:[]});notice('Biblioteca de ejemplo: 11 referencias de CA2 y métodos. Las conexiones iniciales se basan en términos.')}catch(e){notice(e.message)}}function replace(data){state=data;selected=null;positions.clear();$('#search').value='';$('#statusFilter').value='';view={x:0,y:0,k:1};save();refresh()}
$('#demo').onclick=loadDemo;$('#file').onchange=async ev=>{const file=ev.target.files[0];if(!file)return;try{if(file.size>5e6)throw Error('El archivo supera 5 MB. Importa una bibliografía más pequeña.');const text=await file.text(),data=file.name.toLowerCase().endsWith('.json')?validateWorkspace(JSON.parse(text)):{version:1,papers:parseBib(text),manual:[]};if(state.papers.length&&!confirm('¿Reemplazar la biblioteca actual? Exporta primero para conservar tus notas.'))return;replace(data);notice(`${state.papers.length} referencias importadas. Notas y lectura se guardan en este navegador.`)}catch(e){notice('No se importó el archivo: '+e.message)}finally{ev.target.value=''}};
$('#export').onclick=()=>{if(!state.papers.length){notice('Importa una biblioteca antes de exportar.');return}const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=el('a',{href:url,download:'atlas-biblioteca.json'});a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice('Biblioteca exportada con notas, estados, metadatos y conexiones. Puedes volver a importar el JSON.')};
$('#enrich').onclick=async()=>{if(busy)return;const papers=state.papers.filter(p=>p.doi&&p.lookup!=='ok');if(!papers.length){notice(state.papers.length?'No hay DOI pendientes de consultar.':'Importa una biblioteca primero.');return}busy=true;$('#enrich').disabled=true;$('#file').disabled=true;$('#demo').disabled=true;let ok=0,failed=0;try{for(let i=0;i<papers.length;i++){const p=papers[i];notice(`Consultando Crossref ${i+1}/${papers.length}: ${p.id}…`);try{const res=await fetch('https://api.crossref.org/works/'+encodeURIComponent(normalizeDoi(p.doi)),{signal:AbortSignal.timeout(16000)});if(!res.ok)throw Error(String(res.status));const {message:m}=await res.json();if(m.abstract){const doc=new DOMParser().parseFromString(m.abstract,'text/html');p.abstract=(doc.body.textContent||'').trim()}p.references=(m.reference??[]).map(r=>normalizeDoi(r.DOI??'')).filter(Boolean);p.lookup='ok';p.lookupDate=new Date().toISOString();ok++}catch{p.lookup='error';failed++}save()}refresh();notice(`Consulta completada: ${ok} artículos recuperados, ${failed} no disponibles. Solo se enlazan citas entre artículos de tu biblioteca; la cobertura puede ser incompleta.`)}finally{busy=false;$('#enrich').disabled=false;$('#file').disabled=false;$('#demo').disabled=false}};
try{const saved=localStorage.getItem(KEY);if(saved){state=validateWorkspace(JSON.parse(saved));notice('Biblioteca recuperada de este navegador. Exporta una copia para conservarla.')}}catch{notice('No se pudo recuperar la biblioteca guardada. Puedes importar una copia JSON.')}refresh();
